    [3153]={name="Oil-stained Cloak",quality=1,ilvl=9,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'Operation Recombobulation'. Pick it over the other reward choices. Starts with Razzle Sprysprocket in Dun Morogh. Objective: Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.",zone="Dun Morogh",questName="Operation Recombobulation",lore="Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes."},
    [3161]={name="Robe of the Keeper",quality=2,ilvl=15,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'Filthy Paws'. Pick it over the other reward choices.",zone="Loch Modan",questName="Filthy Paws",lore="The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!"},
    [3216]={name="Warm Winter Robe",quality=1,ilvl=10,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'Frostmane Hold'. Pick it over the other reward choices. Starts with Senir Whitebeard in Dun Morogh. Objective: Explore Frostmane Hold, and kill 5 Frostmane Headhunters for Senir Whitebeard in Kharanos.",zone="Dun Morogh",questName="Frostmane Hold",lore="I'm behind on my report, and could use your help. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in."},
    [3224]={name="Silver-lined Bracers",quality=2,ilvl=12,reqLevel=7,sourceType="rare_npc",instructions="Drops from Timber.",zone="Dun Morogh",npc="Timber"},
